insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('5ea3323c-a01f-43bc-96d9-1da5e63c3e6a', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$inleiding: Janneke heeft een geelbruin randje in haar ogen$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context1.png$$,
   $$Toen Jannekes vriend opmerkte dat haar ogen van kleur leken te veranderen, dacht ze dat hij een grapje maakte. Maar in de spiegel ziet ze tussen het blauw en het wit van haar ogen een randje geelbruin. Voor de zekerheid gaat zij naar de dokter. Die vermoedt dat Janneke de ziekte van Wilson heeft.$$, 'inline'),
  ('bbe4ccd2-b760-4673-aa70-d18767bee565', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$ziekte van Wilson: koper hoopt zich op in de lever en aan de rand van het hoornvlies$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context2.png$$,
   $$De ziekte van Wilson is een zeldzame aandoening waarbij de uitscheiding van koper is verstoord. Hierdoor hoopt koper zich op in de lever, maar ook aan de rand van het hoornvlies, waardoor de verkleuringen ontstaan.$$, 'inline'),
  ('4d6a9ed9-391d-4c5d-bc8e-2f10d48c515e', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$doorsnede van het oog met letters$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context3.png$$,
   $$In afbeelding 1 is in een doorsnede van het oog een aantal plaatsen met letters aangegeven.$$, 'inline'),
  ('9dfe1cdd-76fc-4bc5-a2ad-69d3a01085fd', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$afbeelding 1: doorsnede van het oog met plaatsen P t/m U$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context4.png$$,
   $$afbeelding 1: doorsnede van het oog met de plaatsen P, Q, R, S, T en U$$, 'inline'),
  ('71bcb443-6784-4a8a-8bc0-9452178ce5d9', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$DNA-onderzoek: gemuteerd gen op chromosoom 13; glutamine in plaats van histidine$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context5.png$$,
   $$De dokter verwijst Janneke door voor DNA-onderzoek. Hiermee wordt de diagnose bevestigd. De internist in het ziekenhuis legt uit dat bij de ziekte van Wilson een gen op chromosoom 13 is gemuteerd. Dit gen codeert normaal voor een eiwit dat levercellen nodig hebben om koper via de gal uit te scheiden. Bij Janneke bevindt zich op een bepaalde plaats in dit eiwit het aminozuur glutamine in plaats van histidine. Hierdoor functioneert dit eiwit niet en hoopt het koper zich eerst op in de lever en in latere stadia ook in andere organen.$$, 'inline'),
  ('71eef841-0ad0-4818-b880-b2b5bb7465cf', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$de mutatie is een puntmutatie$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context6.png$$,
   $$De mutatie die leidt tot de ziekte van Wilson is een puntmutatie.$$, 'inline'),
  ('605a496d-8493-4628-9bda-842d719b185b', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$het eiwit voor koperuitscheiding bevindt zich in organel P$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context7.png$$,
   $$Het eiwit dat betrokken is bij de koperuitscheiding bevindt zich bij gezonde personen in het organel dat in afbeelding 2 met letter P is aangegeven.$$, 'inline'),
  ('f23dcb6a-38d3-497d-893f-f2c9ff56aff5', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$afbeelding 2: deel van een cel met kern, endoplasmatisch reticulum, celmembraan en P$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context8.png$$,
   $$afbeelding 2: tekening van een deel van een cel met kern, endoplasmatisch reticulum, celmembraan en een organel aangegeven met P$$, 'inline'),
  ('682991c2-0850-47e1-9b53-4e34a9eeb4b2', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$koper wordt actief opgenomen in de darmen en uitgescheiden door de lever$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context9.png$$,
   $$Koper wordt actief opgenomen in de darmen en komt via het bloed in de lever. Bij gezonde mensen wordt 80 tot 90 procent van het opgenomen koper weer uitgescheiden door de lever.$$, 'inline'),
  ('c25b3d36-b7de-4ca6-839b-f15a383b8125', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$doorsnede van een leverlobje; galgang en bloedvaten genummerd$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context10.png$$,
   $$In afbeelding 3 is een doorsnede van een deel van een leverlobje te zien. De galgang en bloedvaten zijn met cijfers aangegeven. Op plaats 1 en 4 stroomt zuurstofarm bloed. De pijlen geven de stroomrichting aan.$$, 'inline'),
  ('90d70b48-0068-4fde-b914-ef86fc94163e', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$afbeelding 3: doorsnede van een deel van een leverlobje met plaatsen 1 t/m 4$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context11.png$$,
   $$afbeelding 3: doorsnede van een deel van een leverlobje; de galgang en de bloedvaten zijn aangegeven met de cijfers 1 t/m 4, pijlen geven de stroomrichting aan$$, 'inline'),
  ('bd335c8b-d3c5-4f7b-b639-ca546498fdae', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$medicijnen en dieet; leverschade en eiwitstofwisseling$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context12.png$$,
   $$Janneke krijgt medicijnen die de koperopname in de darmen afremmen. Ook moet ze een dieet volgen om leverschade te voorkomen. Door leverschade kunnen problemen ontstaan met de stofwisseling van eiwitten.$$, 'inline'),
  ('6402c7b8-1d4f-4428-9941-896003ee02a9', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$afbeelding 4: stamboom van de familie van Janneke$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context13.png$$,
   $$De ziekte van Wilson blijkt vaker voor te komen in de familie van Janneke. In afbeelding 4 is de stamboom van Jannekes familie te zien.
afbeelding 4: stamboom van de familie van Janneke met onder anderen overgrootvader, overgrootmoeder, oma Rita, tante Sylvia, Sem en Janneke. Legenda: open symbool = gezond, zwart symbool = ziekte van Wilson. Sem en Janneke hebben de ziekte van Wilson.$$, 'inline'),
  ('10c2a062-5186-4f52-8c57-df6f4a06eb18', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$autosomale overerving; bij X-chromosomale overerving zou een ouder ziek moeten zijn$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context14.png$$,
   $$Uit de stamboom is af te leiden dat de ziekte van Wilson autosomaal overerft. Als de overerving X-chromosomaal was geweest, zou een van de ouders van Sem of Janneke de ziekte ook moeten hebben.$$, 'inline'),
  ('33476071-6e4f-4c17-b03b-4aa5df6af61f', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$tante Sylvia wil weten of ze drager is; oma Rita is geen drager$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context15.png$$,
   $$Jannekes tante Sylvia (afbeelding 4) wil weten wat de kans is dat ze drager is van het allel voor de ziekte van Wilson. Ga ervan uit dat Jannekes oma Rita geen drager is.$$, 'inline'),
  ('c127d9e0-fda2-4e6b-91d9-655a8151beb4', 'c27ab548-4025-4916-9f27-8b9cb3126a8f', $$levertransplantatie geneest de ziekte van Wilson$$,
   $$biologie-havo-2019-ii-de-ziekte-van-wilson-context16.png$$,
   $$Als de ziekte van Wilson niet wordt behandeld kan leverschade optreden. Bij zeer ernstige leverschade is een levertransplantatie nodig. Dit is een zware operatie, maar hiermee is de patiënt ook genezen van de ziekte van Wilson.$$, 'inline'),
  ('ce73294a-ac7c-4cd5-893c-c2816cfb47a0', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$inleiding: hoofdluis loopt over bij een selfie (afbeelding 1)$$,
   $$biologie-havo-2019-ii-hoofdluis-context1.png$$,
   $$Even de hoofden bij elkaar voor een selfie? Best kans dat er tijdens het maken van een selfie (afbeelding 1) een hoofdluis overloopt naar een ander hoofd.
afbeelding 1: foto van drie meisjes die een selfie maken$$, 'inline'),
  ('3b39880f-5579-4d78-8b6e-771ebc4ab704', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$hoofdluis (afbeelding 2) en dikte van een mensenhaar; aanpassing van de poten$$,
   $$biologie-havo-2019-ii-hoofdluis-context2.png$$,
   $$afbeelding 2: foto van een hoofdluis
Een volwassen hoofdluis (afbeelding 2) is 2,5 tot 3 mm groot. Een mensenhaar heeft een gemiddelde dikte van 0,1 mm. De poten van hoofdluizen hebben een aanpassing waardoor ze geschikt zijn voor het voortbewegen via haren.$$, 'inline'),
  ('871bb3c7-9cf8-4b90-b559-8cda7aeecd60', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$jeuk als afweerreactie op speeksel van de hoofdluis; mestcel en histamine$$,
   $$biologie-havo-2019-ii-hoofdluis-context3.png$$,
   $$Hoofdluizen zuigen bloed uit de hoofdhuid van mensen. Dit kan leiden tot jeuk. Jeuk is het gevolg van een reactie van het afweersysteem op stoffen uit het speeksel van de hoofdluis. In afbeelding 3 is deze reactie schematisch weergegeven. Mediatoren (zoals histamine) die afgegeven worden door de mestcel zijn verantwoordelijk voor het ontstaan van jeuk.$$, 'inline'),
  ('15bcc287-b462-482e-8a74-883f9b12c2c0', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$afbeelding 3: schema van de afweerreactie met lymfocyten P en Q en stof R$$,
   $$biologie-havo-2019-ii-hoofdluis-context4.png$$,
   $$afbeelding 3: schema van de afweerreactie: 1e contact met antigeen via een antigeen-presenterende cel naar lymfocyt P en lymfocyt Q, die stof R maakt; R bindt aan een mestcel; bij 2e contact met antigeen geeft de mestcel o.a. histamine af, wat leidt tot jeuk.
In afbeelding 3 geven P en Q bepaalde lymfocyten aan. Met R wordt een bepaalde stof aangegeven.$$, 'inline'),
  ('13e997ea-a5e5-4a08-ae60-d269879800d4', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$malathion remt het enzym dat de neurotransmitter afbreekt$$,
   $$biologie-havo-2019-ii-hoofdluis-context5.png$$,
   $$Hoofdluis kan bestreden worden met anti-luizenshampoos die malathion bevatten. Deze chemische stof veroorzaakt de dood van een hoofdluis doordat het de impulsoverdracht van motorische zenuwcellen naar de spiercellen bij de hoofdluis verstoort: malathion remt het enzym dat de neurotransmitter afbreekt.$$, 'inline'),
  ('baa5d976-2641-43b9-b9c5-96a3992be878', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$deels ingevuld schema van de werking van malathion$$,
   $$biologie-havo-2019-ii-hoofdluis-context6.png$$,
   $$In afbeelding 4 is de werking van malathion in een deels ingevuld schema weergegeven.$$, 'inline'),
  ('0ec3c90f-b299-4ea8-9de9-f9cc38d5dfa6', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$afbeelding 4: deels ingevuld schema werking malathion$$,
   $$biologie-havo-2019-ii-hoofdluis-context7.png$$,
   $$afbeelding 4: deels ingevuld schema met drie lege invulplaatsen, twee cirkels en de pijl naar acetaat + choline$$, 'inline'),
  ('edda1b87-dd7e-4e40-aa89-857eb31dba6f', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$het schema staat ook in de uitwerkbijlage$$,
   $$biologie-havo-2019-ii-hoofdluis-context8.png$$,
   $$In de uitwerkbijlage staat dit schema nogmaals afgebeeld.$$, 'inline'),
  ('61bf8be9-1b25-4de4-a2b9-2610c148c02f', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$hoofdluis ontwikkelt resistentie tegen malathion$$,
   $$biologie-havo-2019-ii-hoofdluis-context9.png$$,
   $$De anti-luizenshampoos met malathion werken steeds minder goed. Dat komt doordat de hoofdluis resistentie ontwikkelt tegen deze stof.$$, 'inline'),
  ('9a4d55bb-3956-4aea-91b3-aed006d3224f', 'c3f3ab54-2859-4b19-a624-83d9687526b0', $$uitwerkbijlage vraag 11: in te vullen schema werking malathion$$,
   $$biologie-havo-2019-ii-hoofdluis-context10.png$$,
   $$11
uitwerkbijlage: schema met drie lege invulplaatsen, twee cirkels en de pijl naar acetaat + choline$$, 'uitwerkbijlage'),
  ('0dc081c9-854b-4c34-b64a-ae49f6f2bd80', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$inleiding: bruinvissen in de Noordzee$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context1.png$$,
   $$De bruinvis is een zeezoogdier van ongeveer anderhalve meter. Door onder andere de verminderde visserijdruk en de verbeterde waterkwaliteit zwemmen er tegenwoordig weer zo’n driehonderdduizend bruinvissen in de Noordzee.$$, 'inline'),
  ('2fb01ff0-3a5d-487e-b753-c46f7821be15', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$jonge bruinvis: 550 vangpogingen per uur, 90% succes, 1 gram per vangst, 2 kg vis per dag nodig$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context2.png$$,
   $$Bruinvissen zijn uitstekende jagers. Onderzoek heeft aangetoond dat jonge bruinvissen per uur 550 pogingen kunnen doen om een prooi te vangen. Ongeveer 90% van deze pogingen is succesvol. Per succesvolle poging wordt een visje van gemiddeld 1 gram gevangen. Per dag heeft een jonge bruinvis 2 kilogram vis nodig.$$, 'inline'),
  ('91989aec-006e-4109-af3e-eca83d0e7081', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$aangespoelde, uitgehongerde bruinvissen; analyse van de maaginhoud (afbeelding 1 en 2)$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context3.png$$,
   $$In de zomermaanden spoelen relatief veel dode bruinvissen aan (afbeelding 1). De aangespoelde dieren blijken uitgehongerd, terwijl er meer dan voldoende voedsel te vinden is. Marien bioloog Mardik Leopold onderzoekt wat de oorzaak is van het verhongeren van de aangespoelde dieren. Hiervoor analyseert hij de maaginhoud (afbeelding 2) van een aangespoelde bruinvis.
afbeelding 1: foto van een aangespoelde bruinvis op het strand
afbeelding 2: foto van de maaginhoud van een bruinvis$$, 'inline'),
  ('065b3d28-3ac7-4801-a9d8-93459c680f2b', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$skeletdelen van prooidieren in de maag$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context4.png$$,
   $$In de maag worden vooral skeletdelen van kreeftachtigen, inktvissen, zeeslakken en vissen aangetroffen. Aan de hand van deze delen kunnen de prooidieren worden gedetermineerd.$$, 'inline'),
  ('a45378d8-b723-40e1-9a9c-6ebf363808ed', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$ook maaginhoud van in netten verdronken bruinvissen onderzocht$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context5.png$$,
   $$In het onderzoek naar de oorzaak van het verhongeren van aangespoelde bruinvissen, onderzocht Leopold ook de maaginhoud van bruinvissen die overleden nadat ze in netten van vissers terecht waren gekomen.$$, 'inline'),
  ('764dfa17-26cd-4a19-8913-d3e9477c59dd', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$vette en magere vissoorten; jonge bruinvissen eten veel grondel$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context6.png$$,
   $$Uit het onderzoek bleek dat bruinvissen veel haring, sprot en zandspiering eten: vette, energierijke vissen. Maar ook magere vissoorten als wijting en grondel staan op het menu. Vooral in jonge aangespoelde bruinvissen wordt veel grondel in de maag aangetroffen. Waarschijnlijk omdat ze nog niet vaardig genoeg zijn om de snel zwemmende haring en sprot te vangen. Hierdoor kan een tekort aan bepaalde voedingsstoffen ontstaan bij de jonge bruinvissen.$$, 'inline'),
  ('b59dffd7-d6ec-439a-a1d1-c00eda5b62be', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$drie groepen voedingsstoffen$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context7.png$$,
   $$Drie groepen voedingsstoffen zijn:
1 bouwstoffen
2 brandstoffen
3 vitamines$$, 'inline'),
  ('c522a583-e710-42c3-91a0-9b56d68c44f9', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$DNA-onderzoek van bijtwonden; monsters 1 t/m 4$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context8.png$$,
   $$Sommige aangespoelde bruinvissen hadden ernstige verwondingen. In eerste instantie werden deze verwondingen toegeschreven aan visnetten of scheepsschroeven. Na vergelijking van deze wonden met het gebit van verschillende zeeroofdieren, leek de grijze zeehond de oorzaak. Om dit te bevestigen, werd bij een aantal verwonde bruinvissen DNA-onderzoek gedaan. Voor dit onderzoek werden met wattenstaafjes monsters verzameld van de volgende delen:
1 gesloten bijtwonden (wonden waar een tand de huid is binnen- gedrongen waarna de huid zich weer heeft gesloten direct na het terugtrekken)
2 open bijtwonden
3 bruinvishuid In deze monsters werd in het laboratorium gezocht naar een stukje DNA dat specifiek is voor de grijze zeehond. Enkele schone wattenstaafjes werden op dezelfde manier getest (monster 4).$$, 'inline'),
  ('9a23ab4c-30ac-467b-a9b3-dbbcf151324e', 'dc6fb764-a721-4c5a-aec5-d01050f17781', $$afbeelding 3: gel met de DNA-resultaten van monsters 1 t/m 4$$,
   $$biologie-havo-2019-ii-bruinvis-verhongert-in-een-zee-vol-vis-context9.png$$,
   $$afbeelding 3: foto van de gel met de monsters 1 t/m 4 op de aangegeven plaatsen
In afbeelding 3 is de foto van de gel weergegeven, waarmee aangetoond werd dat de grijze zeehond inderdaad de veroorzaker is van de verwondingen bij de bruinvissen. De monsters 1 tot en met 4 zijn op de aangegeven plaatsen aangebracht.$$, 'inline'),
  ('52e69330-4ae4-44af-9b5b-847939605dd9', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$inleiding: dodelijke paardenziekte met verhoogde spierafbraak (afbeelding 1)$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context1.png$$,
   $$Bij paarden en pony’s (afbeelding 1) treedt soms plotseling een dodelijke ziekte op, waarbij onder andere sprake is van een verhoogde spierafbraak. Wetenschappers uit Wageningen onderzoeken wat de oorzaak kan zijn van deze mysterieuze ziekte.
afbeelding 1: foto van paarden in een wei$$, 'inline'),
  ('70e6624c-c98e-444b-916b-2bece7c07470', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$atypische myopathie: komt voor in de wei, niet rasgebonden, niet afhankelijk van verwantschap$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context2.png$$,
   $$De ziekte wordt atypische myopathie genoemd. Ze breekt vaak uit in het najaar en komt alleen voor bij paarden die in de wei staan. Meestal worden meerdere paarden uit dezelfde wei ziek. Paarden in een aangrenzende wei, met als enige afscheiding prikkeldraad, blijven vaak ongedeerd. De ziekte is niet specifiek voor bepaalde paardenrassen en voor het ontstaan van de aandoening in een groep paarden maakt het niet uit of de paarden verwant zijn aan elkaar.$$, 'inline'),
  ('28ab437b-4de8-4fa3-ba66-3b54cc18b45a', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$de ziekte is waarschijnlijk niet erfelijk of besmettelijk$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context3.png$$,
   $$Uit de tekst is af te leiden dat atypische myopathie waarschijnlijk geen erfelijke of besmettelijke ziekte is.$$, 'inline'),
  ('0e4f1fd9-3a9e-432d-9804-383ce5923a12', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$moeite met ademhalen door aantasting van ademhalingsspieren$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context4.png$$,
   $$Een van de symptomen van atypische myopathie is moeite met ademhalen. Dit wordt veroorzaakt door aantasting van ademhalingsspieren.$$, 'inline'),
  ('d2f859c2-7449-4f4e-af17-269a878951fa', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$hypoglycine-A uit esdoornzaden (afbeelding 2 en 3); opname van stoffen via twee routes$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context5.png$$,
   $$Waarschijnlijk wordt de ziekte veroorzaakt door het eten van afgevallen bladeren en zaden van esdoorns die bij de weiden staan. Vooral in de zaden, bekend als helikoptertjes (afbeelding 2), zit de stof hypoglycine-A (afbeelding 3). Deze stof remt een belangrijk enzym bij paarden, waardoor ze ziek worden.
afbeelding 2: foto van een esdoornzaad (helikoptertje)
afbeelding 3: structuurformule van hypoglycine-A
Om hypoglycine-A te kunnen maken, moet de esdoorn verschillende stoffen opnemen uit zijn omgeving. In afbeelding 4 staan twee delen van de plant. Twee routes waarlangs esdoorns stoffen opnemen uit de omgeving en verder transporteren, zijn met genummerde pijlen aangegeven.$$, 'inline'),
  ('dc92d477-7f17-4967-9007-ad09388bcd4a', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$afbeelding 4: twee delen van de plant met routes 1 en 2$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context6.png$$,
   $$afbeelding 4: twee delen van de plant met de genummerde routes 1 en 2$$, 'inline'),
  ('836ef5b7-79b0-440e-b491-f832f00dd8dd', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$water via route 1; andere stoffen als bouwstof voor hypoglycine-A$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context7.png$$,
   $$De plant neemt water op via route 1. Naast water zijn er nog andere stoffen nodig die de esdoorn moet opnemen als bouwstof voor hypoglycine-A.$$, 'inline'),
  ('7524e15a-e1a6-40af-91ba-adeacdd3bb18', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$esdoorngroepen (tabel 1), tweet (afbeelding 5) en hypoglycine-A-concentraties (tabel 2)$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context8.png$$,
   $$In Nederland komen vooral de gewone esdoorn (Acer pseudoplatanus), de Noorse esdoorn (Acer platanoides) en de Spaanse aak (Acer campestre) voor. Maar er zijn tientallen esdoornsoorten. De soorten worden op basis van verwantschap ingedeeld in groepen (tabel 1).
tabel 1
| groep | enkele soorten |
| Negundo | Acer negundo; Acer cissifolium |
| Platanoidea | Acer platanoides; Acer campestre |
| Acer | Acer pseudoplatanus; Acer saccharum; Acer velutinum |
| Palmata | Acer palmatum |
Om esdoorns uit Nederland te kunnen onderzoeken, werd door het onderzoeksteam van Wageningen Universiteit en Research een tweet geplaatst (afbeelding 5).
afbeelding 5: tweet van Wageningen UR: "Sommige esdoornzaden blijken giftig voor paarden. Stuur ''helikoptertjes'' naar @RIKILT_WUR om ze te laten onderzoeken."
De verzamelde monsters werden geanalyseerd. De eerste resultaten zijn weergegeven in tabel 2.
tabel 2
| groep | aantal monsters | aantal monsters met hypoglycine-A | gemiddelde concentratie hypoglycine-A (mg/kg) |
| Negundo | 2 | 2 | 218,0 |
| Platanoidea | 7 | 0 | 0 |
| Acer | 6 | 6 | 1004,3 |
| Palmata | 3 | 3 | 14,5 |$$, 'inline'),
  ('2f0a911e-cc06-4b50-b5cd-999530634bcb', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$evolutionaire stamboom van de esdoorngroepen met voorouders 1 t/m 4$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context9.png$$,
   $$De evolutionaire stamboom van de vier groepen esdoorns is in afbeelding 6 weergegeven. Vier voorouders zijn met een nummer aangegeven.$$, 'inline'),
  ('1e15d014-de14-4dcb-90b3-0f27b1d6aeb3', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$afbeelding 6: evolutionaire stamboom van Negundo, Platanoidea, Acer en Palmata$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context10.png$$,
   $$afbeelding 6: evolutionaire stamboom van de groepen Negundo, Platanoidea, Acer en Palmata met de voorouders 1, 2, 3 en 4$$, 'inline'),
  ('238230e5-eaa0-4a81-b337-7eb328b53580', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$hypoglycineproductie afkomstig van gemeenschappelijke voorouder 1$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context11.png$$,
   $$Er wordt van uitgegaan dat alle huidige esdoornsoorten die hypoglycine produceren deze eigenschap van de gemeenschappelijke voorouder (nummer 1) hebben gekregen.$$, 'inline'),
  ('f8671d04-395e-44ba-98e9-4c9ed69bf4f4', 'c43b645a-1df7-40ff-9f77-61150b2c8120', $$Sofie heeft een paard in een wei met Spaanse aken$$,
   $$biologie-havo-2019-ii-mysterieuze-paardenziekte-context12.png$$,
   $$Sofie heeft een paard in een weiland met Spaanse aken (Acer campestre) eromheen. Naar aanleiding van het Wageningse onderzoek vraagt ze zich af of zij haar paard naar een andere wei moet overbrengen om het te beschermen tegen atypische myopathie.$$, 'inline'),
  ('06e65a52-6190-4713-ae24-68e78f6e2a8e', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$inleiding: Karin eet vegetarisch$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context1.png$$,
   $$Karin eet al een aantal jaren vegetarisch. In die jaren heeft ze steeds meer argumenten gevonden die haar keuze ondersteunen geen vlees meer te eten.$$, 'inline'),
  ('d6b2ddce-47a6-4801-9ade-dc3c1085cc5c', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$vleesproductie niet duurzaam: methaan, stikstofkringloop, landbouwgrond$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context2.png$$,
   $$De productie van vlees is in vergelijking met de productie van plantaardig voedsel niet erg duurzaam, want:
− bij veeteelt komt het broeikasgas methaan vrij;
− de import van veevoer uit andere continenten verstoort de stikstofkringloop, zowel in het land waar planten voor het veevoer worden geteeld als in het land van de vleesproductie;
− voor een kilogram vlees is veel meer landbouwgrond nodig dan voor een kilogram plantaardig voedsel met een gelijkwaardige voedingswaarde, zoals peulvruchten en noten.$$, 'inline'),
  ('f8f2c0ff-245b-403d-a722-b37d8def0180', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$voedingswaarde als eiwitbron; onmisbare aminozuren$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context3.png$$,
   $$Met de voedingswaarde wordt in dit geval de bruikbaarheid van het voedsel als eiwitbron bedoeld. De eiwitten uit peulvruchten bevatten − net als vlees − bepaalde aminozuren die onmisbaar zijn in onze voeding, zoals valine, threonine en lysine.$$, 'inline'),
  ('8e5df5ed-dab0-4af9-ab86-29128518a329', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$geïmporteerd veevoer en eutrofiëring; stikstofstromen in afbeelding 1$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context4.png$$,
   $$Gebruik van geïmporteerd veevoer kan leiden tot eutrofiëring in de gebieden waar de veeteelt plaatsvindt. In afbeelding 1 zijn de voornaamste stikstofstromen die worden beïnvloed door deze veeteelt in een schema weergegeven.$$, 'inline'),
  ('1f058901-139c-4516-9381-46d8259f191f', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$afbeelding 1: schema van stikstofstromen bij veeteelt (onvolledig in de PDF)$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context5.png$$,
   $$afbeelding 1: schema van de voornaamste stikstofstromen bij veeteelt: eiwitten in de plant (uit de bodem) worden als veevoer verplaatst naar het vee; eiwitten in het vee gaan naar vlees en urine; NH₃ gaat naar de atmosfeer; in de bodem vinden omzettingen plaats (lege vakken). Legenda: gestippelde pijl = verplaatsing, doorgetrokken pijl = omzetting.
⚠️ CONTROLEREN: in de bron-PDF is de onderkant van deze afbeelding (vak met NO₃⁻ / NH₄⁺ en oppervlaktewater, legenda ''omzetting'') bij de conversie naar de volgende pagina verschoven en onleesbaar; het volledige schema staat in de uitwerkbijlage bij vraag 26.$$, 'inline'),
  ('14162b55-cc18-4ab2-af00-121de490f8ff', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$het schema is niet compleet; ook in de uitwerkbijlage$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context6.png$$,
   $$Het schema in afbeelding 1 is niet compleet. In de uitwerkbijlage is het schema nogmaals afgebeeld.$$, 'inline'),
  ('613bccd1-6c53-49b6-a90b-78c87acd4ac4', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$insecten als eiwitbron met hoge voedselconversie$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context7.png$$,
   $$Tijdens een kookworkshop maakt Karin kennis met een alternatieve eiwitbron: insecten, zoals sprinkhanen en meelwormen. Deze dieren zijn makkelijk te kweken. Ook hebben insecten een hoge voedselconversie: voor een kilogram rundvlees is tien kilogram voer nodig, voor een kilogram insecten slechts drie kilogram.$$, 'inline'),
  ('935f9d05-b2dc-4ca1-9c78-ac7a1919ed32', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$allergie voor garnalen en mogelijk voor meelwormen; bloedtest$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context8.png$$,
   $$Karin vraagt zich af of ze een allergische reactie zal krijgen als ze insecten eet. Ze heeft namelijk een allergie voor garnalen. De eiwitten van deze verschillende diersoorten lijken zo veel op elkaar dat een allergie voor garnalen misschien ook een allergie voor meelwormen kan betekenen. Karin wil haar bloed laten testen om te kijken of het eten van meelwormen voor haar problemen zal opleveren.$$, 'inline'),
  ('ecbb496c-c6fd-4f21-9a60-ade3ff7ced74', 'e5b38217-b9db-4185-aaef-ee53ebe8998e', $$uitwerkbijlage vraag 26: schema van stikstofstromen bij veeteelt$$,
   $$biologie-havo-2019-ii-het-smaakt-naar-nootjes-maar-dan-met-pootjes-context9.png$$,
   $$26
uitwerkbijlage: schema van de voornaamste stikstofstromen bij veeteelt met vijf lege vakken: plant (eiwitten) en bodem; veevoer (eiwitten), vee (eiwitten), vlees (eiwitten), urine, NH₃, atmosfeer (NH₃); drie vakken in de bodem; oppervlaktewater (NO₃⁻, NH₄⁺). Legenda: gestippelde pijl = verplaatsing, doorgetrokken pijl = omzetting.$$, 'uitwerkbijlage'),
  ('3b9fdf90-2329-44df-a116-d6895c62d68e', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$inleiding: prenatale diagnostiek en de NIPT$$,
   $$biologie-havo-2019-ii-nipt-context1.png$$,
   $$Verloskundige Chantal bespreekt met vrouwen die in verwachting zijn en hun partners de mogelijkheden van prenatale diagnostiek. Bij prenatale diagnostiek kunnen chromosoomafwijkingen, zoals bij het syndroom van Down, aan het licht komen. De NIPT (niet-invasieve prenatale test) is een van de mogelijke prenatale tests.$$, 'inline'),
  ('05f47745-af17-4c5b-a217-eddad4af5856', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$een kind met downsyndroom heeft drie chromosomen 21$$,
   $$biologie-havo-2019-ii-nipt-context2.png$$,
   $$Een kind met downsyndroom heeft drie chromosomen 21.$$, 'inline'),
  ('e18b9e74-8c0d-42f3-98ff-adba22e07a2b', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$drie uitspraken over het downsyndroom$$,
   $$biologie-havo-2019-ii-nipt-context3.png$$,
   $$Over het downsyndroom worden drie uitspraken gedaan.
1 Het syndroom is een gevolg van een genoommutatie.
2 Het extra chromosoom 21 kan van de vader afkomstig zijn.
3 De drie chromosomen 21 zijn identiek.$$, 'inline'),
  ('b2723960-3ec4-4cde-b1cd-7076b70d22f4', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$DNA-fragmenten van de foetus komen via de placenta in het bloed van de moeder$$,
   $$biologie-havo-2019-ii-nipt-context4.png$$,
   $$Met de NIPT kan door onderzoek van het bloed van de moeder onderzocht worden of de foetus mogelijk een afwijkend chromosomenaantal heeft. DNA-fragmenten van de foetus komen vrij uit afgestorven cellen van de placenta (afbeelding 1) en worden in het bloed van de moeder opgenomen.$$, 'inline'),
  ('c21ad4e6-5b41-461a-89d2-e68690b40892', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$afbeelding 1: placenta met bloed van foetus en moeder en DNA-fragmenten$$,
   $$biologie-havo-2019-ii-nipt-context5.png$$,
   $$afbeelding 1: schematische tekening van de placenta met bloed van de foetus en bloed van de moeder, bloedvaten van foetus en moeder; legenda: DNA-fragment foetus, DNA-fragment moeder$$, 'inline'),
  ('9db7728f-57c5-4b79-88f3-4f8261e72ca6', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$bloed wordt afgenomen uit de rechterarmader (afbeelding 2)$$,
   $$biologie-havo-2019-ii-nipt-context6.png$$,
   $$Het bloed met DNA-fragmenten van de foetus wordt bij een zwangere vrouw vanuit de rechterarmader afgenomen (afbeelding 2).
afbeelding 2: foto van bloedafname bij een zwangere vrouw$$, 'inline'),
  ('ac4b88e9-5b7f-4dd3-b150-c997abf60088', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$lijst van negen bloedvaten$$,
   $$biologie-havo-2019-ii-nipt-context7.png$$,
   $$Bloedvaten in het lichaam van deze vrouw zijn:
1 aorta
2 armader
3 armslagader
4 baarmoederader
5 baarmoederslagader
6 bovenste holle ader
7 longader
8 longslagader
9 onderste holle ader$$, 'inline'),
  ('9f448a30-4565-4785-bcd2-c0b00be12f6c', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$foetale DNA-fragmenten scheiden en toewijzen aan chromosomen$$,
   $$biologie-havo-2019-ii-nipt-context8.png$$,
   $$De DNA-fragmenten van de foetus die in de bloedbaan van de moeder circuleren, zijn kleiner zijn dan de DNA-fragmenten van de moeder zelf. Hierdoor kunnen ze van elkaar worden gescheiden. Vervolgens wordt bepaald van welke chromosomen de DNA-fragmenten van de foetus afkomstig zijn. Als er relatief veel fragmenten van chromosoom 21 zijn, is dat waarschijnlijk het gevolg van een derde chromosoom 21.$$, 'inline'),
  ('22e12dd5-a482-43e4-8bdc-37a68663345c', '1d776f1e-e8a5-49b7-bef7-9a98cea89b39', $$aanvullend onderzoek na afwijkende NIPT; voordeel voor ouders$$,
   $$biologie-havo-2019-ii-nipt-context9.png$$,
   $$Als in een NIPT afwijkingen worden geconstateerd, is aanvullend onderzoek nodig om een diagnose te kunnen stellen. Ouders kunnen dan beslissen om een zwangerschap af te breken. Chantal weet dat veel ouders dit niet zullen doen. Toch kan de NIPT voor deze toekomstige ouders een voordeel bieden.$$, 'inline'),
  ('4892e941-98c7-463a-8bce-57e67b115176', 'afa2f879-aac7-40b5-841b-29f92147f474', $$inleiding: onderzoek naar aanpassing van de kanoet aan klimaatverandering$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context1.png$$,
   $$Jan van Gils, bioloog bij het NIOZ (Koninklijk Nederlands Instituut voor Onderzoek der Zee) doet onderzoek naar hoe de kanoet (Calidris canutus, afbeelding 1) zich aanpast aan klimaatverandering.$$, 'inline'),
  ('c75d0e42-1b48-47d7-a4d6-f77ef5439f46', 'afa2f879-aac7-40b5-841b-29f92147f474', $$afbeelding 1: foto van een kanoet$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context2.png$$,
   $$afbeelding 1: foto van een kanoet$$, 'inline'),
  ('33bec9d3-aa92-49e8-a239-5f179b857697', 'afa2f879-aac7-40b5-841b-29f92147f474', $$gevoelige snavelpunt; schelp verbrijzeld in de spiermaag$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context3.png$$,
   $$Kanoeten zoeken de schelpdieren waarvan ze leven door hun snavel in het zand te steken. Het puntje van de snavel is extreem gevoelig en kan drukverschillen in het natte zand waarnemen, waardoor de vogel weet waar de prooi zich bevindt. Vervolgens wordt de schelp in zijn geheel ingeslikt en in de spiermaag verbrijzeld, waarna de zachte delen worden verteerd.$$, 'inline'),
  ('7f4da33d-2ae4-4e6c-ae72-1a73762aabac', 'afa2f879-aac7-40b5-841b-29f92147f474', $$trekroute van broedgebied naar Mauritanië met tussenstops (afbeelding 2)$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context4.png$$,
   $$De kanoet broedt in het Noordpoolgebied en overwintert in tropische waddengebieden in Mauritanië. Tijdens de trek van broedgebied naar overwinteringsgebied maken de vogels een tussenstop aan de Bocht van Gdansk (Polen) en bij de Nederlandse Waddenzee (afbeelding 2). Vooral de jonge dieren vullen hier hun vetreserves aan. De kanoeten verblijven van eind augustus tot begin mei in Mauritanië.
afbeelding 2: kaart van de trekroute van het Noordpoolgebied (Rusland) via de Bocht van Gdansk en de Nederlandse Waddenzee naar het waddengebied van Mauritanië$$, 'inline'),
  ('a876fdd6-93b0-4ea1-8af1-37c7f28f0698', 'afa2f879-aac7-40b5-841b-29f92147f474', $$reservevoedsel als vet of glycogeen; energie-inhoud per gram$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context5.png$$,
   $$Trekvogels zoals de kanoet slaan hun reservevoedsel op in de vorm van vet. Reserves kunnen ook aangelegd worden in de vorm van koolhydraten zoals glycogeen. Vetten leveren 38 Joule per gram, koolhydraten leveren 17 Joule per gram.$$, 'inline'),
  ('44285b6b-ed58-4f0d-8086-408ad3bd639d', 'afa2f879-aac7-40b5-841b-29f92147f474', $$kanoeten worden kleiner; hypothese over warmteafgifte$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context6.png$$,
   $$Sinds 1983 worden in Gdansk jaarlijks kanoeten gemeten en gewogen. Hieruit blijkt dat de gemiddelde grootte van de kanoeten afneemt. Een hypothese hiervoor is dat door de wereldwijde opwarming van het klimaat kleinere kanoeten in het voordeel zijn ten opzichte van grotere kanoeten. Door hun kleinere bouw zouden ze namelijk beter hun warmte kwijt kunnen raken.$$, 'inline'),
  ('ee9c2e3a-6c3b-4946-85d9-7053330708cd', 'afa2f879-aac7-40b5-841b-29f92147f474', $$kuikens eten insecten tot de sneeuw smelt; metingen in Gdansk$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context7.png$$,
   $$De kuikens van de kanoeten komen rond een vaste datum (eind juni) uit hun ei en verlaten vrijwel meteen het nest. De kuikens eten voornamelijk insecten die in de grond overwinteren. Zodra in het poolgebied de dooi invalt en de sneeuw smelt, kruipen deze insecten uit de grond en zijn daarna niet meer beschikbaar voor de jonge kanoeten. In afbeelding 3 zijn de resultaten te zien van metingen gedaan tijdens de trek in augustus in het tussenstation Gdansk. Het gemiddelde gewicht van de jonge kanoeten is uitgezet tegen de datum waarop de sneeuw in het broedgebied is gesmolten dat jaar. Te zien is dat in 2015 de sneeuw was gesmolten op 17 juni en het gemiddelde gewicht van de jonge kanoeten bij de meting in augustus 102 gram was.$$, 'inline'),
  ('d679421f-235c-4de2-a373-5ced4a899a91', 'afa2f879-aac7-40b5-841b-29f92147f474', $$afbeelding 3: gewicht jonge kanoeten tegen smeltdatum sneeuw$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context8.png$$,
   $$afbeelding 3: puntgrafiek van het gewicht van jonge kanoeten (gram, 90-125) tegen de smeltdatum van de sneeuw (20 juni - 20 juli), met een stijgende trendlijn; het punt van 2015 is aangegeven$$, 'inline'),
  ('f0e923cb-2c9a-48c1-936c-16e16253ec69', 'afa2f879-aac7-40b5-841b-29f92147f474', $$klimaatverandering als oorzaak van het kleiner blijven$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context9.png$$,
   $$Wetenschappers denken dat klimaatverandering de oorzaak is van het kleiner blijven van de jonge kanoeten.$$, 'inline'),
  ('82bded82-3b7d-47ba-9371-e713447c6819', 'afa2f879-aac7-40b5-841b-29f92147f474', $$kortere snavel en ingraafdiepte van voedselbronnen (afbeelding 4)$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context10.png$$,
   $$Het kleinere lichaam betekent ook een kortere snavel (afbeelding 4). Dit heeft grote gevolgen voor het voedselzoeken in Mauritanië. Het schelpdier Loripes lucinalis komt in hoge dichtheden voor en vormt nu nog de belangrijkste prooi van de kanoet. Een ander schelpdier dat wordt gegeten is Dosinia isocardia, hiervan is de populatiedichtheid veel lager. Kanoeten eten ook wortels van zeegras (Zostera noltii), maar deze bevatten relatief weinig voedingsstoffen. Op welke diepte deze drie voedselbronnen zich voornamelijk bevinden is weergeven in afbeelding 4.
afbeelding 4: kop van een kanoet naast een diagram van de ingraafdiepte (0-50 mm) van Loripes lucinalis, Dosinia isocardia en Zostera noltii; Loripes lucinalis zit het diepst, Zostera noltii het minst diep$$, 'inline'),
  ('e8b9e3aa-3579-4d6f-ac1f-3e90fe50a45a', 'afa2f879-aac7-40b5-841b-29f92147f474', $$drie uitspraken over gevolgen van de veranderde lichaamsbouw$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context11.png$$,
   $$Over de gevolgen van de veranderingen in lichaamsbouw worden drie uitspraken gedaan:
1 Doordat kleinere kanoeten van meer voedselbronnen gebruik gaan maken, behoren ze tot een hoger trofisch niveau dan grotere kanoeten.
2 Een kanoet met een snavel korter dan 30 mm kan minder Loripes lucinalis vangen dan een kanoet met een langere snavel.
3 Kanoeten met een kortere snavel moeten meer tijd besteden aan voedsel zoeken dan kanoeten met een langere snavel.$$, 'inline'),
  ('2d85970f-b79a-477e-9b57-261931fe0926', 'afa2f879-aac7-40b5-841b-29f92147f474', $$voorspelde evolutie naar een kleinere kanoet met langere snavel (afbeelding 5)$$,
   $$biologie-havo-2019-ii-kanoet-met-te-korte-snavel-context12.png$$,
   $$afbeelding 5: tekening van de huidige kanoet (links) en de veel kleinere kanoet van de toekomst (rechts)
Van Gils verwacht dat het voedselprobleem van de kanoet effect heeft op de evolutie van de soort. In afbeelding 5 is weergegeven hoe hij denkt dat de kanoet zich zou kunnen ontwikkelen. Links staat de huidige kanoet, rechts de veel kleinere kanoet van de toekomst. De kleinere kanoet ontwikkelt een langere snavel volgens de voorspelling van Van Gils.$$, 'inline'),
  ('ecb33c7d-a18b-481c-aed2-c7939a718196', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$inleiding: energiedrankjes en hartproblemen bij jongeren$$,
   $$biologie-havo-2019-ii-energiedrankjes-context1.png$$,
   $$Mario en Hannah drinken, net als veel andere jongeren, regelmatig een energiedrankje. Toch is het gebruik van energiedrankjes niet zonder risico’s: steeds meer jongeren komen met hartproblemen in het ziekenhuis.$$, 'inline'),
  ('61a88d8f-28f6-4484-bd1c-5cb50172ed2a', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$energiedrankjes met suiker en cafeïne; Mario leert 's nachts door$$,
   $$biologie-havo-2019-ii-energiedrankjes-context2.png$$,
   $$Energiedrankjes (energydrinks) bevatten een hoge concentratie suiker en cafeïne. Daarnaast zijn andere oppeppende stoffen toegevoegd. Mario drinkt energiedrankjes wanneer hij tot diep in de nacht doorleert voor een proefwerk. Hij heeft ervaren dat dit zijn concentratie vergroot en hem wakker houdt.$$, 'inline'),
  ('be88024b-7003-4b35-be1b-11ca1d40a0c8', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$lengtedoorsnede van hersenen en ruggenmerg met letters$$,
   $$biologie-havo-2019-ii-energiedrankjes-context3.png$$,
   $$In afbeelding 1 zijn in een lengtedoorsnede van de hersenen en een deel van het ruggenmerg de verschillende delen met letters aangegeven.$$, 'inline'),
  ('4a2c2ff5-c02a-4919-803e-d44e52702189', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$afbeelding 1: lengtedoorsnede hersenen en deel ruggenmerg met P t/m T$$,
   $$biologie-havo-2019-ii-energiedrankjes-context4.png$$,
   $$afbeelding 1: lengtedoorsnede van de hersenen en een deel van het ruggenmerg met de delen P, Q, R, S en T$$, 'inline'),
  ('8be07f4e-ab89-4b9f-8be3-d92687f2242b', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$cafeïne wordt opgenomen in het bloed en deels afgebroken in de lever$$,
   $$biologie-havo-2019-ii-energiedrankjes-context5.png$$,
   $$Een half uur na het drinken van een energiedrankje zijn vrijwel alle cafeïnemoleculen opgenomen in Mario’s bloed. In de lever wordt een deel van de cafeïne afgebroken. Mario merkt anderhalf uur na het drinken dat hij zich weer minder goed kan concentreren.$$, 'inline'),
  ('7f75281a-06dd-4c23-979f-6529633c8242', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$adenosine bindt aan receptoren in synapsen; cafeïne blokkeert deze$$,
   $$biologie-havo-2019-ii-energiedrankjes-context6.png$$,
   $$Naarmate je langer wakker bent, hoopt de stof adenosine zich op in de hersenen. Adenosine bindt aan receptoren in de synapsen van hersencellen, waardoor er minder gemakkelijk impulsen worden overgedragen. Dit leidt tot slaperigheid. Cafeïne kan deze receptoren blokkeren, zodat adenosine niet kan binden. Mario voelt zich hierdoor minder moe. In afbeelding 2 worden schematisch twee zenuwcellen in de hersenen weergegeven.$$, 'inline'),
  ('49f88f7f-bcfa-419e-a768-57d0eea722ac', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$afbeelding 2: twee zenuwcellen P en Q met richting van de impuls$$,
   $$biologie-havo-2019-ii-energiedrankjes-context7.png$$,
   $$afbeelding 2: schema van twee zenuwcellen, zenuwcel P en zenuwcel Q, met de richting van de impuls$$, 'inline'),
  ('f6a03022-7c0f-4abc-98dc-d2ce6ad23fea', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$adenosine werkt vergelijkbaar met bepaalde neurotransmitters$$,
   $$biologie-havo-2019-ii-energiedrankjes-context8.png$$,
   $$De werking van adenosine in de synaps is vergelijkbaar met de werking van bepaalde neurotransmitters.$$, 'inline'),
  ('f428518c-dd67-4895-afc5-9d76e85409b3', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$cafeïne stimuleert een deel van het autonome zenuwstelsel; hart en bloeddruk$$,
   $$biologie-havo-2019-ii-energiedrankjes-context9.png$$,
   $$Inname van een energiedrankje heeft effect op de werking van het hart en op de bloeddruk. Dit komt doordat cafeïne een stimulerend effect heeft op een bepaald deel van het autonome zenuwstelsel.$$, 'inline'),
  ('83fa377c-7e83-4a25-9326-555e12820ade', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$Hannah drinkt energiedrank tijdens het wielrennen$$,
   $$biologie-havo-2019-ii-energiedrankjes-context10.png$$,
   $$Hannah is wielrenster. Tijdens haar ritten drinkt ze soms een blikje energiedrank om haar vocht- en brandstofvoorraad aan te vullen.$$, 'inline'),
  ('64cf0d69-6f0d-4435-9fb1-83f8c80f07b7', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$glycogeenvoorraad en 'pap in de benen'; drie gebeurtenissen$$,
   $$biologie-havo-2019-ii-energiedrankjes-context11.png$$,
   $$Hannahs glycogeenvoorraad is genoeg voor zestig tot negentig minuten intensief sporten. Tijdens langere ritten neemt ze koolhydraten in om te voorkomen dat ze ‘pap in de benen’ krijgt. Wielrenners bedoelen daarmee dat ze onvoldoende kracht in hun benen hebben om het hoge tempo vol te kunnen houden. Gebeurtenissen die hierbij plaatsvinden zijn:
1 afname van de dissimilatie
2 uitputting van de glycogeenvoorraad in de spiercellen
3 vermindering van samentrekking van de spiervezels$$, 'inline'),
  ('63a896e8-f2f6-45c3-aa56-39c343154a4b', 'f68cf162-bdd1-4a69-9eca-e8ad089f4b48', $$cafeïne beïnvloedt de afgifte van ADH; meer wateruitscheiding$$,
   $$biologie-havo-2019-ii-energiedrankjes-context12.png$$,
   $$Hannah’s trainster raadt Hannah af nog langer energiedrank te drinken tijdens het sporten, omdat het uitdroging kan veroorzaken. Doordat cafeïne de afgifte van antidiuretisch hormoon (ADH) beïnvloedt, leidt gebruik van energiedrankjes tot een toename van de wateruitscheiding.$$, 'inline');

